package local.wallpanel.app;
import java.io.*;
import java.net.*;
import java.util.*;
import java.util.regex.*;
import javax.net.SocketFactory;

/** Video-only RTSP/TCP. PLAY occurs only when the user receives a call. */
final class RtspVideoSession implements Closeable {
    interface Listener {void phase(String name);void parameters(byte[] sps,byte[] pps)throws Exception;void frame(byte[] annexB,long pts)throws Exception;}
    private final SocketFactory sockets;private final Listener listener;private final URI endpoint;private final String user,password,url;
    private volatile boolean closed;private volatile Socket socket;private InputStream in;private OutputStream out;private int cseq,nonceCount,payload,channel;private String session="",challenge="";private long lastPacket;
    private static final class Reply {int code;Map<String,String> headers=new HashMap<String,String>();String body="";}
    RtspVideoSession(String address,SocketFactory factory,Listener sink)throws Exception{endpoint=new URI(address);String info=endpoint.getUserInfo();int split=info==null?-1:info.indexOf(':');user=info==null?"":split<0?info:info.substring(0,split);password=split<0?"":info.substring(split+1);url=new URI(endpoint.getScheme(),null,endpoint.getHost(),endpoint.getPort(),endpoint.getPath(),endpoint.getQuery(),null).toASCIIString();sockets=factory;listener=sink;}
    void describeOnly()throws Exception{try{socket=sockets.createSocket();if(closed)return;socket.connect(InetSocketAddress.createUnresolved(endpoint.getHost(),endpoint.getPort()>0?endpoint.getPort():554),5000);socket.setSoTimeout(5000);in=socket.getInputStream();out=socket.getOutputStream();Reply r=request("DESCRIBE",url,"Accept: application/sdp\r\n");require(r);videoTrack(r.body,r.headers.get("content-base"));}finally{close();}}
    void run()throws Exception{
        try{listener.phase("connecting");socket=sockets.createSocket();if(closed)return;socket.connect(InetSocketAddress.createUnresolved(endpoint.getHost(),endpoint.getPort()>0?endpoint.getPort():554),5000);socket.setSoTimeout(3000);in=socket.getInputStream();out=socket.getOutputStream();
            Reply description=request("DESCRIBE",url,"Accept: application/sdp\r\n");require(description);String control=videoTrack(description.body,description.headers.get("content-base"));listener.phase("setting_up");
            Reply setup=request("SETUP",control,"Transport: RTP/AVP/TCP;unicast;interleaved=0-1\r\n");require(setup);session=setup.headers.containsKey("session")?setup.headers.get("session").split(";",2)[0]:"";if(session.length()==0)throw new IOException("Missing RTSP session");String transport=setup.headers.get("transport");Matcher channels=Pattern.compile("interleaved=(\\d+)-(\\d+)").matcher(transport==null?"":transport);if(!channels.find())throw new IOException("Camera did not accept interleaved RTP");channel=Integer.parseInt(channels.group(1));
            listener.phase("waiting_for_h264");require(request("PLAY",url,"Range: npt=0.000-\r\n"));lastPacket=System.currentTimeMillis();long keepalive=lastPacket;
            H264RtpAssembler parser=new H264RtpAssembler(payload,new H264RtpAssembler.Output(){public void parameters(byte[] sps,byte[] pps)throws Exception{listener.parameters(sps,pps);}public void frame(byte[] bytes,long pts)throws Exception{listener.frame(bytes,pts);}});
            while(!closed){long now=System.currentTimeMillis();if(now-keepalive>15000){send("OPTIONS",url,"");keepalive=now;}int first;try{first=in.read();}catch(SocketTimeoutException idle){if(System.currentTimeMillis()-lastPacket>10000)throw new IOException("Camera stream timed out");continue;}if(first<0)throw new EOFException();if(first=='$'){int ch=readByte(),n=(readByte()<<8)|readByte();byte[] bytes=exact(n);if(ch==channel){lastPacket=System.currentTimeMillis();parser.packet(bytes,bytes.length);}}else if(first=='R'){reply(first);}else throw new IOException("Invalid RTSP frame");}
        }finally{try{if(!closed&&out!=null&&session.length()>0)send("TEARDOWN",url,"");}catch(Exception ignored){}close();}
    }
    private String videoTrack(String sdp,String base)throws Exception{String selected=null;boolean video=false;int pt=-1;StringBuilder section=new StringBuilder();
        for(String line:sdp.split("\\r?\\n")){line=line.trim();if(line.startsWith("m=")){if(video)break;String[] fields=line.substring(2).split("\\s+");video=fields.length>=4&&fields[0].equals("video");if(video)pt=Integer.parseInt(fields[3]);}else if(video){section.append(line).append('\n');if(line.startsWith("a=control:"))selected=line.substring(10).trim();}}
        Matcher codec=Pattern.compile("(?m)^a=rtpmap:(\\d+) H264/90000\\s*$",Pattern.CASE_INSENSITIVE).matcher(section);if(!codec.find()||selected==null||selected.equals("*"))throw new IOException("Camera does not provide an H264 video track");payload=Integer.parseInt(codec.group(1));URI origin=new URI(base==null?url:base);return origin.resolve(selected).toASCIIString();
    }
    private Reply request(String method,String target,String extra)throws Exception{for(int attempt=0;attempt<2;attempt++){send(method,target,extra);Reply r=reply(readByte());if(r.code!=401)return r;String next=r.headers.get("www-authenticate");if(next==null)throw new IOException("Missing RTSP authentication challenge");if(!challenge.equals(next))nonceCount=0;challenge=next;}throw new IOException("RTSP authentication rejected");}
    private void send(String method,String target,String extra)throws Exception{if(closed)throw new IOException("Video stopped");String headers=method+" "+target+" RTSP/1.0\r\nCSeq: "+(++cseq)+"\r\nUser-Agent: TuyaHAWallPanel\r\n"+extra;if(session.length()>0)headers+="Session: "+session+"\r\n";if(challenge.length()>0)headers+="Authorization: "+authorization(method,target)+"\r\n";out.write((headers+"\r\n").getBytes("UTF-8"));out.flush();}
    private String authorization(String method,String target)throws Exception{if(!challenge.regionMatches(true,0,"Digest ",0,7))throw new IOException("Unsupported RTSP authentication");Map<String,String> d=new HashMap<String,String>();Matcher m=Pattern.compile("(\\w+)\\s*=\\s*(?:\"([^\"]*)\"|([^,\\s]+))").matcher(challenge.substring(7));while(m.find())d.put(m.group(1).toLowerCase(Locale.US),m.group(2)!=null?m.group(2):m.group(3));String realm=d.get("realm"),nonce=d.get("nonce"),algorithm=d.containsKey("algorithm")?d.get("algorithm"):"MD5",qop="";if(realm==null||nonce==null)throw new IOException("Invalid RTSP authentication");if(d.containsKey("qop")){for(String q:d.get("qop").split(","))if(q.trim().equals("auth"))qop="auth";if(qop.length()==0)throw new IOException("Unsupported RTSP authentication quality");}String nc=String.format(Locale.US,"%08x",++nonceCount),cnonce=UUID.randomUUID().toString().replace("-","");String value="Digest username="+quote(user)+", realm="+quote(realm)+", nonce="+quote(nonce)+", uri="+quote(target)+", response="+quote(SipDigest.response(user,realm,password,method,target,nonce,algorithm,qop,nc,cnonce))+", algorithm="+quote(algorithm);if(qop.length()>0)value+=", qop=auth, nc="+nc+", cnonce="+quote(cnonce);else if(algorithm.toLowerCase(Locale.US).endsWith("-sess"))value+=", cnonce="+quote(cnonce);if(d.containsKey("opaque"))value+=", opaque="+quote(d.get("opaque"));return value;}
    private static String quote(String s)throws IOException{if(s.indexOf('\r')>=0||s.indexOf('\n')>=0)throw new IOException("Invalid authentication field");return "\""+s.replace("\\","\\\\").replace("\"","\\\"")+"\"";}
    private void require(Reply r)throws IOException{if(r.code!=200)throw new IOException("RTSP status "+r.code);}
    private int readByte()throws IOException{int b=in.read();if(b<0)throw new EOFException();return b;}
    private byte[] exact(int n)throws IOException{if(n<0||n>65536)throw new IOException("RTSP body too large");byte[] b=new byte[n];int at=0,count;while(at<n){count=in.read(b,at,n-at);if(count<0)throw new EOFException();at+=count;}return b;}
    private String line(int first)throws IOException{ByteArrayOutputStream b=new ByteArrayOutputStream();int next=first;while(next!='\n'){if(next!='\r')b.write(next);if(b.size()>8192)throw new IOException("RTSP line too long");next=readByte();}return new String(b.toByteArray(),"UTF-8");}
    private Reply reply(int first)throws Exception{Reply r=new Reply();String status=line(first);if(!status.matches("RTSP/1\\.[01] [0-9]{3}.*"))throw new IOException("Invalid RTSP response");r.code=Integer.parseInt(status.substring(9,12));for(int count=0;count<100;count++){String h=line(readByte());if(h.length()==0){int n=r.headers.containsKey("content-length")?Integer.parseInt(r.headers.get("content-length")):0;r.body=new String(exact(n),"UTF-8");return r;}int split=h.indexOf(':');if(split>0){String name=h.substring(0,split).trim().toLowerCase(Locale.US),value=h.substring(split+1).trim();String previous=r.headers.get(name);if(!name.equals("www-authenticate")||previous==null||(!previous.regionMatches(true,0,"Digest ",0,7)&&value.regionMatches(true,0,"Digest ",0,7)))r.headers.put(name,value);}}throw new IOException("RTSP headers too large");}
    public void close(){closed=true;Socket s=socket;if(s!=null)try{s.close();}catch(IOException ignored){}}
}
